const clock = new THREE.Clock();

// Cinematic renderer setup
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Light neutral background for readability
scene.background = new THREE.Color(0xf0f2f5);
scene.fog = new THREE.Fog(0xf0f2f5, 10, 50);

// Three-point cinematic lighting
const keyLight = new THREE.DirectionalLight(0xfff8e7, 2.0);
keyLight.position.set(8, 12, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 40;
keyLight.shadow.camera.left = -10;
keyLight.shadow.camera.right = 10;
keyLight.shadow.camera.top = 10;
keyLight.shadow.camera.bottom = -10;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xd6e6ff, 0.8);
fillLight.position.set(-8, 6, 4);

const rimLight = new THREE.SpotLight(0x4d8aff, 1.5);
rimLight.position.set(0, 8, -8);
rimLight.lookAt(0, 0, 0);
rimLight.penumbra = 0.5;

const ambientLight = new THREE.AmbientLight(0x404050, 0.6);
scene.add(ambientLight, keyLight, fillLight, rimLight);

// Environment map for realistic PBR
const rgbeLoader = new THREE.RGBELoader();
rgbeLoader.load('/vendor/env/venice_sunset_1k.hdr', function(texture) {
  texture.mapping = THREE.EquirectangularReflectionMapping;
  scene.environment = texture;
  scene.backgroundBlurriness = 0.2;
});

// Fusion core group
const fusionGroup = new THREE.Group();
scene.add(fusionGroup);

// Central fusion core - high emissive energy sphere
const coreGeo = new THREE.SphereGeometry(1.2, 64, 32);
const coreMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  emissive: 0xff4400,
  emissiveIntensity: 2.0,
  metalness: 0.1,
  roughness: 0.2,
  transmission: 0.6,
  thickness: 1.5,
  clearcoat: 1.0,
  clearcoatRoughness: 0.1
});
const core = new THREE.Mesh(coreGeo, coreMat);
core.castShadow = true;
fusionGroup.add(core);

// Inner plasma layer
const plasmaGeo = new THREE.SphereGeometry(0.9, 64, 32);
const plasmaMat = new THREE.MeshBasicMaterial({
  color: 0xffaa00,
  transparent: true,
  opacity: 0.8
});
const plasma = new THREE.Mesh(plasmaGeo, plasmaMat);
fusionGroup.add(plasma);

// Magnetic containment rings (torus)
const ringGroup = new THREE.Group();
fusionGroup.add(ringGroup);

for (let i = 0; i < 3; i++) {
  const ringGeo = new THREE.TorusGeometry(2.5 + i * 0.8, 0.08, 16, 100);
  const ringMat = new THREE.MeshStandardMaterial({
    color: 0x8899aa,
    metalness: 0.9,
    roughness: 0.2,
    emissive: 0x2244aa,
    emissiveIntensity: 0.3
  });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.rotation.x = Math.PI / 2;
  ring.rotation.y = (i * Math.PI) / 3;
  ring.castShadow = true;
  ring.receiveShadow = true;
  ringGroup.add(ring);
}

// Approaching mass spheres (fusion reactants)
const massGroup = new THREE.Group();
fusionGroup.add(massGroup);

const massGeo = new THREE.SphereGeometry(0.6, 64, 32);
const massMat = new THREE.MeshPhysicalMaterial({
  color: 0x3366cc,
  metalness: 0.7,
  roughness: 0.3,
  clearcoat: 0.5,
  emissive: 0x112244,
  emissiveIntensity: 0.2
});

const leftMass = new THREE.Mesh(massGeo, massMat);
leftMass.position.set(-3, 0, 0);
leftMass.castShadow = true;
massGroup.add(leftMass);

const rightMass = new THREE.Mesh(massGeo, massMat);
rightMass.position.set(3, 0, 0);
rightMass.castShadow = true;
massGroup.add(rightMass);

// Energy particles streaming toward center
const particleCount = 800;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);
const particleVelocities = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  const angle = Math.random() * Math.PI * 2;
  const radius = 4 + Math.random() * 6;
  const y = (Math.random() - 0.5) * 4;

  particlePositions[i * 3] = Math.cos(angle) * radius;
  particlePositions[i * 3 + 1] = y;
  particlePositions[i * 3 + 2] = Math.sin(angle) * radius;

  // Velocity toward center
  particleVelocities[i * 3] = -particlePositions[i * 3] * 0.3;
  particleVelocities[i * 3 + 1] = -y * 0.3;
  particleVelocities[i * 3 + 2] = -particlePositions[i * 3 + 2] * 0.3;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0xff6600,
  size: 0.06,
  transparent: true,
  opacity: 0.8,
  sizeAttenuation: true,
  blending: THREE.AdditiveBlending
});
const particles = new THREE.Points(particleGeo, particleMat);
fusionGroup.add(particles);

// Floor plane for grounding
const floorGeo = new THREE.CircleGeometry(20, 128);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0xe8eaed,
  roughness: 0.4,
  metalness: 0.3
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -4;
floor.receiveShadow = true;
scene.add(floor);

// Camera setup
camera.position.set(8, 5, 8);
camera.lookAt(0, 0, 0);

// OrbitControls with damping
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);
controls.minDistance = 5;
controls.maxDistance = 25;
controls.maxPolarAngle = Math.PI / 2 + 0.1;
controls.update();

// Animation loop
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Rotate containment rings
  ringGroup.children.forEach((ring, i) => {
    ring.rotation.z = t * (0.2 + i * 0.1);
    ring.rotation.x = (Math.PI / 2) + Math.sin(t * 0.5 + i) * 0.1;
  });

  // Pulse the fusion core
  const pulse = 1 + Math.sin(t * 3) * 0.1;
  core.scale.setScalar(pulse);
  plasma.scale.setScalar(0.9 * pulse);
  coreMat.emissiveIntensity = 2.0 + Math.sin(t * 4) * 0.5;

  // Animate approaching masses (fusion motion)
  const approach = Math.sin(t * 0.8) * 0.5 + 0.5; // 0 to 1
  leftMass.position.x = -3 + approach * 1.5;
  rightMass.position.x = 3 - approach * 1.5;
  leftMass.rotation.y = t * 0.5;
  rightMass.rotation.y = -t * 0.5;

  // Update particles - spiral toward center
  const positions = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    const ix = i * 3;
    const iy = i * 3 + 1;
    const iz = i * 3 + 2;

    // Move toward center with spiral motion
    positions[ix] += particleVelocities[ix] * 0.016 + Math.sin(t + i) * 0.02;
    positions[iy] += particleVelocities[iy] * 0.016;
    positions[iz] += particleVelocities[iz] * 0.016 + Math.cos(t + i) * 0.02;

    // Reset if too close to center
    const dist = Math.sqrt(positions[ix]**2 + positions[iy]**2 + positions[iz]**2);
    if (dist < 1.5) {
      const angle = Math.random() * Math.PI * 2;
      const radius = 8 + Math.random() * 4;
      positions[ix] = Math.cos(angle) * radius;
      positions[iy] = (Math.random() - 0.5) * 4;
      positions[iz] = Math.sin(angle) * radius;
    }
  }
  particles.geometry.attributes.position.needsUpdate = true;
  particles.rotation.y = t * 0.2;

  // Dynamic lighting based on fusion intensity
  keyLight.intensity = 2.0 + Math.sin(t * 3) * 0.3;
  rimLight.intensity = 1.5 + Math.cos(t * 2) * 0.4;

  controls.update();
  renderer.render(scene, camera);
}

animate();

