      positions[iz] = Math.sin(angle) * radius;
    }
  }
  particles.geometry.attributes.position.needsUpdate = true;
  particles.rotation.y = t * 0.2;

  // Dynamic lighting based on fusion intensity
  keyLight.intensity = 2.0 + Math.sin(t * 3) * 0.3;
  rimLight.intensity = 1.5 + Math.cos(t * 2) * 0.4;

  controls.update();
  renderer.render(scene, camera);
}

animate();
